package lk.medical.model;
public abstract class Doctor { private String id,name,specialization,availability,roomNumber,email,password,type; private double fee; public Doctor(){} public Doctor(String id,String name,String specialization,String availability,String roomNumber,String email,String password,double fee,String type){this.id=id;this.name=name;this.specialization=specialization;this.availability=availability;this.roomNumber=roomNumber;this.email=email;this.password=password;this.fee=fee;this.type=type;} public abstract double calculateConsultationFee();
 public String getId(){return id;} public void setId(String v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getSpecialization(){return specialization;} public void setSpecialization(String v){specialization=v;} public String getAvailability(){return availability;} public void setAvailability(String v){availability=v;} public String getRoomNumber(){return roomNumber;} public void setRoomNumber(String v){roomNumber=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public double getFee(){return fee;} public void setFee(double v){fee=v;} public String getType(){return type;} public void setType(String v){type=v;}
}
